scwin.gridView1_oncellclick = function(row, col) {
    if (col == 0) {
        var val = dataList1.getCellData(row, "chk");
        var r_idx = gridView1.getRealRowIndex(row);
        if (val == "1") {
            dataList1.deleteRow(r_idx);
        } else {
            dataList1.undeleteRow(r_idx);
        }
    }
};
scwin.__hasClass = function() {
    var el0 = ((j) => j.length ? j : $('#mf_gridView1_body_tbody tr'))($('#gridView1_body_tbody tr'))[0].childNodes[0];
    var el1 = ((j) => j.length ? j : $('#mf_gridView1_body_tbody tr'))($('#gridView1_body_tbody tr'))[1].childNodes[0];
    var el2 = ((j) => j.length ? j : $('#mf_gridView1_body_tbody tr'))($('#gridView1_body_tbody tr'))[2].childNodes[0];
    var el3 = ((j) => j.length ? j : $('#mf_gridView1_body_tbody tr'))($('#gridView1_body_tbody tr'))[3].childNodes[0];
    return scwin.__getJq(el0).hasClass("w2grid_rowStatus_D") && scwin.__getJq(el1).hasClass("w2grid_rowStatus_D") && scwin.__getJq(el2).hasClass("w2grid_rowStatus_D") && scwin.__getJq(el3).hasClass("w2grid_rowStatus_D");
}
scwin.__notHasClass = function() {
    var el0 = ((j) => j.length ? j : $('#mf_gridView1_body_tbody tr'))($('#gridView1_body_tbody tr'))[0].childNodes[0];
    var el1 = ((j) => j.length ? j : $('#mf_gridView1_body_tbody tr'))($('#gridView1_body_tbody tr'))[1].childNodes[0];
    var el2 = ((j) => j.length ? j : $('#mf_gridView1_body_tbody tr'))($('#gridView1_body_tbody tr'))[2].childNodes[0];
    var el3 = ((j) => j.length ? j : $('#mf_gridView1_body_tbody tr'))($('#gridView1_body_tbody tr'))[3].childNodes[0];
    return (!scwin.__getJq(el0).hasClass("w2grid_rowStatus_D")) && (!scwin.__getJq(el1).hasClass("w2grid_rowStatus_D")) && (!scwin.__getJq(el2).hasClass("w2grid_rowStatus_D")) && (!scwin.__getJq(el3).hasClass("w2grid_rowStatus_D"));
}
